          { zh: "我們應該在晚上八點左右發文，因為那時粉絲最活躍。", en: "We should post around 8 p.m., because that's when our followers are most active.", alt: ["We should post at around 8 p.m. because that's when our followers are most active.","We should post around eight in the evening, because that's when our followers are most active.","We should post around 8 p.m., since that's when our followers are most active."], note: "that's when… = 那就是…的時候" },
          { zh: "自從演算法改變後，我們的自然觸及率掉了快一半。", en: "Since the algorithm changed, our organic reach has dropped by almost half.", alt: ["Since the algorithm changed, our organic reach has dropped by nearly half.","Our organic reach has dropped by almost half since the algorithm changed.","Since the algorithm changed, our organic reach has fallen by almost half."], note: "since + 過去式 → 主句用現在完成式 has dropped；organic reach = 自然觸及" },
          { zh: "我們打算和幾位網紅合作，來提高品牌知名度。", en: "We're planning to work with a few influencers to raise brand awareness.", alt: ["We're planning to work with a few influencers to increase brand awareness.","We plan to collaborate with a few influencers to raise brand awareness.","We're planning to partner with a few influencers to build brand awareness."], note: "to + V 表目的；brand awareness = 品牌知名度" },
          { zh: "請在下班前把下個月的內容排程表寄給我。", en: "Please send me next month's content calendar before the end of the day.", alt: ["Please send me next month's content calendar by the end of the day.","Please send me the content calendar for next month before the end of the day.","Could you send me next month's content calendar before the end of the day?"], note: "content calendar = 內容排程表；by / before the end of the day = 今天下班前" },
          { zh: "有幾則負評正在擴散，我們需要在一小時內回應。", en: "A few negative comments are spreading, and we need to respond within an hour.", alt: ["A few negative comments are spreading, so we need to respond within an hour.","A few negative reviews are spreading, and we need to respond within an hour.","Some negative comments are spreading, and we need to respond within an hour."], note: "within an hour = 一小時內；are spreading（現在進行式）" },
          { zh: "使用者生成的內容通常比品牌自己拍的廣告更有說服力。", en: "User-generated content is usually more convincing than ads the brand makes itself.", alt: ["User-generated content is usually more convincing than ads made by the brand itself.","User-generated content is often more persuasive than the brand's own ads.","UGC is usually more convincing than ads the brand makes itself."], note: "user-generated content（UGC）= 使用者生成內容，不可數" },
          { zh: "這支短影片在短短三天內就累積了超過一百萬次觀看。", en: "This short video got over a million views in just three days.", alt: ["This short video racked up over a million views in just three days.","This short video got more than a million views in just three days.","This short video got over one million views in just three days."], note: "rack up = 累積；over / more than a million views" },
          { zh: "我們的粉絲大多是二十五到三十四歲、住在都市的女性。", en: "Most of our followers are women aged 25 to 34 who live in cities.", alt: ["Most of our followers are women aged twenty-five to thirty-four who live in cities.","Most of our followers are urban women aged 25 to 34.","The majority of our followers are women aged 25 to 34 who live in cities."], note: "aged 25 to 34 = 年齡 25 到 34 歲；who live in… 關係子句" },
          { zh: "如果我們每天發限時動態，粉絲會覺得跟品牌更親近。", en: "If we post stories every day, our followers will feel closer to the brand.", alt: ["If we post Stories daily, our followers will feel closer to the brand.","If we post stories every day, our followers will feel more connected to the brand.","If we post stories every day, followers will feel closer to the brand."], note: "If + 現在式, will…（可能發生的條件）" },
          { zh: "這次抽獎帶來很多新粉絲，但大部分都不是我們的目標客群。", en: "The giveaway brought in a lot of new followers, but most of them aren't our target audience.", alt: ["The giveaway brought in lots of new followers, but most of them aren't our target audience.","The giveaway attracted a lot of new followers, but most of them aren't our target audience.","The giveaway brought in many new followers, but most of them aren't in our target audience."], note: "bring in → brought in；target audience = 目標客群" },
          { zh: "與其追求粉絲數，我們更應該專注在真正會購買的人身上。", en: "Instead of chasing follower counts, we should focus on people who will actually buy.", alt: ["Rather than chasing follower counts, we should focus on people who will actually buy.","Instead of chasing follower numbers, we should focus on the people who will actually buy.","Instead of chasing followers, we should focus on people who will actually make a purchase."], note: "instead of + V-ing；people who… 關係子句" }
